"use client"

import React from "react"
import { Suspense, useEffect, useMemo, useState } from "react"
import { ConnectKitProvider, createConfig } from "@particle-network/connectkit"
import { mainnet, polygon, base } from "@particle-network/connectkit/chains"
import { authWalletConnectors } from "@particle-network/connectkit/auth";

const particleEnv = {
    projectId: process.env.NEXT_PUBLIC_PROJECT_ID?.trim(),
    clientKey: process.env.NEXT_PUBLIC_CLIENT_KEY?.trim(),
    appId: process.env.NEXT_PUBLIC_APP_ID?.trim(),
}

const missingParticleEnvKeys = Object.entries(particleEnv)
    .filter(([, value]) => !value)
    .map(([key]) => key)

function ParticleConfigNotice() {
    return (
        <div className="rounded-lg border border-yellow-500 bg-yellow-900/20 p-4 text-left text-sm text-yellow-100">
            <p className="font-semibold">Particle auth is not configured for this environment.</p>
            <p className="mt-2">Add the missing `NEXT_PUBLIC_*` values to your local env file:</p>
            <p className="mt-2 font-mono text-xs break-all">
                {missingParticleEnvKeys.join(", ")}
            </p>
        </div>
    )
}

export function ParticleConnectProvider({
    children,
    fallback,
}: {
    children: React.ReactNode
    fallback?: React.ReactNode
}) {
    const [isMounted, setIsMounted] = useState(false)

    useEffect(() => {
        setIsMounted(true)
    }, [])

    const config = useMemo(() => {
        if (typeof window === "undefined" || missingParticleEnvKeys.length > 0) {
            return null
        }

        return createConfig({
            projectId: particleEnv.projectId!,
            clientKey: particleEnv.clientKey!,
            appId: particleEnv.appId!,
            appearance: {
                mode: "auto",
                connectorsOrder: ["social", "email"],
            },
            walletConnectors: [
                authWalletConnectors({
                    authTypes: ["email", "google", "apple", "twitter", "github"],
                }),
            ],
            chains: [mainnet, polygon, base],
        })
    }, [])

    if (missingParticleEnvKeys.length > 0) {
        return <>{fallback ?? <ParticleConfigNotice />}</>
    }

    if (!isMounted || !config) {
        return <div>Loading Particle Connect...</div>
    }

    return (
        <Suspense fallback={<div>Loading Particle Connect...</div>}>
            <ConnectKitProvider config={config}>{children}</ConnectKitProvider>
        </Suspense>
    )
}

