 28→  async logInWithEmailPassword({ email, password }: { email: string; password: string }): Promise<AuthResponse> {
 29→    await this.ensureInitialized()
 30→    const auth = await Authentication.fromStorage(this.storage)
 31→    if (auth) {
 32→      throw new SessionError(OPENFORT_AUTH_ERROR_CODES.ALREADY_LOGGED_IN, 'Already logged in')
 33→    }
 34→
 35→    this.eventEmitter.emit(OpenfortEvents.ON_AUTH_INIT, { method: 'email' })
 36→
 37→    try {
 38→      const result = await this.authManager.loginEmailPassword(email, password)
 39→      if (result?.token === null) {
 40→        return result
 41→      }
 42→      new Authentication('session', result.token, result.user?.id).save(this.storage)
 43→      this.eventEmitter.emit(OpenfortEvents.ON_AUTH_SUCCESS, result)
 44→      return result
 45→    } catch (error) {
 46→      this.eventEmitter.emit(OpenfortEvents.ON_AUTH_FAILURE, error as Error)
 47→      throw error
 48→    }
