 63→const AutomaticRecovery = ({
 64→  onSuccess,
 65→  handleSetMessage,
 66→}: {
 67→  onSuccess: () => void
 68→  handleSetMessage: (message: string) => void
 69→}) => {
 70→  const [isLoading, setIsLoading] = useState(false)
 71→  const [error, setError] = useState<string | null>(null)
 72→  const [errorModal, setErrorModal] = useState<string | null>(null)
 73→  const [showOTPRequest, setShowOTPRequest] = useState(false)
 74→  const [showOTPVerification, setShowOTPVerification] = useState(false)
 75→  const [userEmail, setUserEmail] = useState('')
 76→  const [otpRequestLoading, setOtpRequestLoading] = useState(false)
 77→  const [otpVerifyLoading, setOtpVerifyLoading] = useState(false)
 78→  const { getEncryptionSession, createWallet, requestOTP, getUserEmail } = useOpenfort()
 79→
 80→  const createWalletWithSession = async (otpCode?: string) => {
 81→    try {
 82→      const encSessionResponse = await getEncryptionSession(otpCode)
 83→      const response = await createWallet({
 84→        recoveryParams: {
 85→          recoveryMethod: RecoveryMethod.AUTOMATIC,
 86→          encryptionSession: encSessionResponse,
 87→        },
 88→      })
 89→      handleSetMessage(`Created a new wallet with automatic recovery.\nwallet: ${JSON.stringify(response, null, 2)}`)
 90→      onSuccess()
 91→    } catch (error) {
 92→      if (error instanceof Error && error.message === 'OTP_REQUIRED') {
 93→        const storedEmail = getUserEmail()
 94→        if (storedEmail) {
 95→          setUserEmail(storedEmail)
 96→          try {
 97→            await requestOTP({ email: storedEmail }, true)
 98→            createWalletWithSession('')
 99→          } catch (otpError) {
100→            if (otpError instanceof Error && otpError.message === 'OTP_RATE_LIMIT') {
101→              setErrorModal('OTP generation rate limit exceeded. Please contact an admin to resolve it.')
102→            } else {
103→              console.error('Error requesting OTP with stored email:', otpError)
104→              setShowOTPRequest(true)
105→            }
106→          }
107→        } else {
108→          setShowOTPRequest(true)
109→        }
110→      } else {
111→        console.error('Error creating wallet:', error)
112→        setError('Failed to create wallet. Check console log for more details.')
113→      }
114→    }
115→  }
116→
117→  const handleOTPRequest = async (contact: { email?: string; phone?: string }) => {
118→    const contactValue = contact.email || contact.phone || ''
