### 8. REACT SDK (`@openfort/react`)

**SSR Compatibility:** All hooks and components are **client-only**. Use `"use client"` directive in Next.js App Router.

#### Provider Setup (with wagmi):

```tsx
// app/providers.tsx
"use client"
import { OpenfortProvider } from '@openfort/react'
import { getDefaultConfig, OpenfortWagmiBridge } from '@openfort/react/wagmi'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { baseSepolia, polygonAmoy } from 'viem/chains'
import { createConfig, WagmiProvider } from 'wagmi'

const config = createConfig(
  getDefaultConfig({
    appName: 'My App',
    chains: [baseSepolia, polygonAmoy],
    walletConnectProjectId: process.env.NEXT_PUBLIC_WC_PROJECT_ID!,
  }),
)

const queryClient = new QueryClient()

export function Providers({ children }: { children: React.ReactNode }) {
  return (
    <QueryClientProvider client={queryClient}>
      <WagmiProvider config={config}>
        <OpenfortWagmiBridge>
          <OpenfortProvider
            publishableKey={process.env.NEXT_PUBLIC_OPENFORT_PUBLIC_KEY!}
            walletConfig={{
              shieldPublishableKey: process.env.NEXT_PUBLIC_SHIELD_API_KEY!,
              ethereum: {
                ethereumFeeSponsorshipId: process.env.NEXT_PUBLIC_POLICY_ID,
                chainId: baseSepolia.id,
                rpcUrls: { [baseSepolia.id]: 'https://sepolia.base.org' },
              },
              connectOnLogin: true,
              createEncryptedSessionEndpoint: '/api/create-encryption-session',
            }}
            uiConfig={{
              authProviders: ['guest', 'emailOtp', 'wallet', 'google'],
            }}
          >
            {children}
          </OpenfortProvider>
        </OpenfortWagmiBridge>
      </WagmiProvider>
    </QueryClientProvider>
  )
}
```

