### 9. SERVER-SIDE: ENCRYPTION SESSIONS (for automatic recovery)

```typescript
// pages/api/create-encryption-session.ts
import type { NextApiRequest, NextApiResponse } from 'next'

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  const shieldUrl = 'https://shield.openfort.io'

  const response = await fetch(`${shieldUrl}/project/encryption-session`, {
    headers: {
      'Content-Type': 'application/json',
      'x-api-key': process.env.SHIELD_PUBLISHABLE_KEY!,      // public key
      'x-api-secret': process.env.SHIELD_SECRET_KEY!,         // secret key
    },
    method: 'POST',
    body: JSON.stringify({
      encryption_part: process.env.SHIELD_ENCRYPTION_SHARE!,  // encryption share
      user_id: req.body.user_id,
      otp_code: req.body.otp_code,                            // optional 2FA
    }),
  })

  const data = await response.json()
  res.status(200).json({ session: data.session_id })
}
```

