 1→import { NextRequest, NextResponse } from 'next/server';
 2→
 3→const SHIELD_URL = process.env.SHIELD_URL || 'https://shield.openfort.io';
 4→const SHIELD_PUBLISHABLE_KEY = process.env.NEXT_PUBLIC_SHIELD_API_KEY;
 5→const SHIELD_SECRET_KEY = process.env.SHIELD_SECRET_KEY;
 6→const SHIELD_ENCRYPTION_SHARE = process.env.SHIELD_ENCRYPTION_SHARE;
 7→
 8→export async function POST(request: NextRequest) {
 9→  if (!SHIELD_PUBLISHABLE_KEY || !SHIELD_SECRET_KEY || !SHIELD_ENCRYPTION_SHARE) {
10→    return NextResponse.json(
11→      { message: 'Shield credentials not configured on server' },
12→      { status: 500 }
13→    );
14→  }
15→
16→  try {
17→    const body = await request.json();
18→
19→    const response = await fetch(`${SHIELD_URL}/project/encryption-session`, {
20→      method: 'POST',
21→      headers: {
22→        'Content-Type': 'application/json',
23→        'x-api-key': SHIELD_PUBLISHABLE_KEY,
24→        'x-api-secret': SHIELD_SECRET_KEY,
25→      },
26→      body: JSON.stringify({
27→        encryption_part: SHIELD_ENCRYPTION_SHARE,
28→        user_id: body.user_id,
29→      }),
30→    });
31→
32→    if (!response.ok) {
33→      const error = await response.text();
34→      console.error('Shield encryption session error:', error);
35→      return NextResponse.json(
36→        { message: 'Failed to create encryption session' },
37→        { status: response.status }
38→      );
39→    }
40→
41→    const data = await response.json();
